insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'lote_8_v1'
from (values
('114.50.c.1.A',3,'A Latin IV student asks a question and adds a detail about time or place. This is a question with:','["simple elaboration", "no content at all", "a footnote only", "a drawn map"]'::jsonb,0,'Elaboration adds detail to a question or answer.','original'),
('114.50.c.1.A',2,'Which pair shows a question answered with simple elaboration?','["Where is the temple? Yes.", "Where is the temple? It stands near the old market.", "Where is the temple? Maybe.", "Where is the temple? Where is the temple?"]'::jsonb,1,'The answer gives extra useful detail.','original'),
('114.50.c.1.B',3,'Saying that you prefer reading history to reading comedy is an example of:','["quoting a law", "translating a coin", "expressing a personal preference", "giving a command"]'::jsonb,2,'Opinions and preferences are exchanged in conversation.','original'),
('114.50.c.1.B',3,'Which sentence best exchanges an opinion with a reason?','["I admire.", "Ask the teacher.", "Orators exist.", "I admire this orator because his arguments are clear."]'::jsonb,3,'A reason makes the opinion more useful.','original'),
('114.50.c.1.C',3,'A classmate says, You must finish the translation tonight. This tells someone what they:','["must do", "may enjoy", "once did", "never saw"]'::jsonb,0,'Must expresses a strong obligation.','original'),
('114.50.c.1.C',3,'Which phrase states advice, not a strict requirement?','["You reviewed yesterday.", "You should review the verb forms.", "You are forbidden to review.", "You must review the verb forms or fail."]'::jsonb,1,'Should is milder than must.','original'),
('114.50.c.2.A',3,'Which source is culturally authentic for a classical language class?','["a modern cartoon with no Latin", "a cooking blog", "an inscription copied from a Roman monument", "a sports score"]'::jsonb,2,'Authentic materials come from the ancient world or its tradition.','original'),
('114.50.c.2.A',3,'Analyzing an authentic audiovisual resource means:','["memorizing its title", "ignoring its content", "only counting its minutes", "looking closely at what it shows about the culture"]'::jsonb,3,'Analysis goes beyond surface description.','original'),
('114.50.c.2.B',3,'Paraphrasing a passage means restating its main idea:','["in your own words", "by deleting it", "by reversing it", "by copying it word for word"]'::jsonb,0,'A paraphrase keeps meaning but changes wording.','original'),
('114.50.c.2.B',3,'Supporting details in a text are used to:','["end the story", "back up the main idea", "replace the title", "hide the theme"]'::jsonb,1,'Details support the central point.','original'),
('114.50.c.2.C',4,'Studying how a poet uses imagery and sound effects is analysis of:','["weather charts", "tax records", "literary devices", "road maps"]'::jsonb,2,'Literary devices shape meaning and style.','original'),
('114.50.c.2.C',4,'Epic, satire and elegy are examples of:','["calendars", "verb endings", "coins", "genres"]'::jsonb,3,'Genre is a category of literature.','original'),
('114.50.c.2.D',3,'If a word in a classical text is unfamiliar, a reader can infer its meaning from:','["the surrounding words and context", "the page number", "the book price", "its font size"]'::jsonb,0,'Context clues reveal meaning.','original'),
('114.50.c.2.D',3,'Recognizing a familiar root inside an unknown word helps you to:','["skip the sentence", "guess its likely meaning", "delete the passage", "change the author"]'::jsonb,1,'Roots carry meaning across related words.','original'),
('114.50.c.2.E',4,'Comparing Roman dinner customs with modern ones is a way to:','["tune an instrument", "measure a field", "contrast cultural practices", "learn a verb ending"]'::jsonb,2,'Compare and contrast reveals similarities and differences.','original'),
('114.50.c.2.E',4,'Which question compares perspectives across cultures?','["What is the date?", "Who owns the book?", "How many letters are in the alphabet?", "How did Romans and modern citizens view public speaking?"]'::jsonb,3,'Perspectives are viewpoints held by a culture.','original'),
('114.50.c.3.A',4,'Citing the justification for an argument means giving:','["the evidence from the text that supports it", "a longer speech", "a louder voice", "a random guess"]'::jsonb,0,'Textual evidence backs up an argument.','original'),
('114.50.c.3.A',4,'Which opinion is justified with textual evidence?','["Speakers exist.", "The speaker is persuasive, since he answers each objection in turn.", "I just feel so.", "The speaker is persuasive."]'::jsonb,1,'The reason points to what the text does.','original'),
('114.50.c.3.B',4,'Reading verse aloud well pays attention to:','["speed only", "skipping lines", "metrical structure and meaningful phrasing", "volume only"]'::jsonb,2,'Meter and phrasing bring out the verse.','original'),
('114.50.c.3.B',3,'Reading prose aloud with good phrasing means:','["reading one letter at a time", "mumbling", "ignoring commas", "grouping words into meaningful units"]'::jsonb,3,'Phrasing keeps ideas together.','original'),
('114.51.c.1.A',4,'At advanced levels, students respond appropriately in an exchange using:','["consistent syntax across time frames", "only single words", "pictures alone", "gestures only"]'::jsonb,0,'Advanced exchanges use steady grammar in past, present and future.','original'),
('114.51.c.1.A',4,'Which skill shows control of a time frame?','["Spelling a name.", "Describing what happened, what is happening and what will happen.", "Counting to three.", "Naming only one noun."]'::jsonb,1,'Time frames are past, present and future.','original'),
('114.51.c.1.B',4,'A written exchange at the right level might provide information on:','["only numbers", "only the weather", "a variety of familiar and academic topics", "nothing specific"]'::jsonb,2,'Written exchanges convey information on many topics.','original'),
('114.51.c.1.B',4,'An email in a classical language asking about a reading assignment is:','["a map", "a monologue only", "a silent film", "a written exchange"]'::jsonb,3,'Exchanges go back and forth between people.','original'),
('114.51.c.2.A',4,'Prepared texts are read after practice; unprepared texts are:','["read without advance study", "only listened to", "never read", "always memorized"]'::jsonb,0,'Unprepared reading is at sight.','original'),
('114.51.c.2.A',4,'Analyzing information from a text involves:','["hiding its genre", "finding and interpreting its key points", "counting pages", "changing its author"]'::jsonb,1,'Analysis is careful interpretation.','original'),
('114.51.c.2.B',4,'Analyzing cultural perspectives from authentic texts helps a student see:','["how to fix a bike", "how to bake bread", "how people of that time viewed the world", "how to program"]'::jsonb,2,'Perspectives are the beliefs behind practices.','original'),
('114.51.c.2.B',4,'Which task contrasts cultural practices?','["Drawing a circle.", "Counting syllables only.", "Copying an alphabet.", "Weighing Greek and Roman attitudes toward theater."]'::jsonb,3,'Contrast looks at differences between cultures.','original'),
('114.51.c.2.C',5,'Style in an author refers to:','["the choices in word order, diction and structure", "the length of the book''s spine", "the price of the book", "the page color"]'::jsonb,0,'Style is the distinctive manner of writing.','original'),
('114.51.c.2.C',5,'Which is a stylistic feature a student might study in verse?','["the book binding", "word order that creates emphasis", "the shelf location", "the publisher"]'::jsonb,1,'Word order shapes emphasis in an inflected language.','original'),
('114.51.c.3.A',5,'Defending an argument with textual evidence at an advanced level means:','["avoiding the text", "asking for a vote", "citing specific passages that support the claim", "repeating the claim louder"]'::jsonb,2,'Specific passages make an argument credible.','original'),
('114.51.c.3.A',5,'An opinion supported by quotation from the original text is:','["irrelevant", "unsupported", "unreadable", "well justified"]'::jsonb,3,'Quoted evidence is strong justification.','original'),
('114.51.c.3.B',5,'Declamation is the skill of:','["reading aloud with meter, meaning and expression", "silent copying", "drawing letters", "counting coins"]'::jsonb,0,'Declamation is expressive oral delivery.','original'),
('114.51.c.3.B',4,'When declaiming a poem, a reader should:','["ignore line endings", "let meter and sense guide the pauses", "skip difficult words", "read at random"]'::jsonb,1,'Meter and meaning guide the pacing.','original'),
('114.52.c.1.A',3,'A good researchable question is one that:','["is already solved", "has no possible answer", "can be investigated with available sources", "needs no evidence"]'::jsonb,2,'Researchable questions can be answered through evidence.','original'),
('114.52.c.1.A',3,'In a seminar, topic questions are approved by:','["the library door", "no one", "a stranger", "the instructor"]'::jsonb,3,'The instructor guides and approves research questions.','original'),
('114.52.c.1.B',3,'Communicating with clarity in a seminar discussion means:','["expressing ideas so others can follow them", "using unclear terms", "speaking as quickly as possible", "avoiding all questions"]'::jsonb,0,'Clear communication supports full participation.','original'),
('114.52.c.1.B',3,'Participating fully in a seminar includes:','["only taking notes", "listening, responding and contributing", "staying silent", "leaving early"]'::jsonb,1,'Participation is active.','original'),
('114.52.c.1.C',4,'Understanding nuance in a language means noticing:','["only length", "only page count", "subtle shades of meaning", "only spelling"]'::jsonb,2,'Nuance is a fine difference in meaning or tone.','original'),
('114.52.c.1.C',4,'Comprehending language within its cultural framework means interpreting it:','["by guessing randomly", "by deleting idioms", "by ignoring context", "as people of that culture would"]'::jsonb,3,'Culture shapes how language is understood.','original'),
('114.52.c.1.D',4,'An in-depth research paper should be built on:','["evidence gathered from many sources", "no sources at all", "a single guess", "one unchecked rumor"]'::jsonb,0,'Research papers rest on evidence.','original'),
('114.52.c.1.D',3,'A summary of a source should:','["add invented facts", "give its main points briefly", "copy every sentence", "skip its topic"]'::jsonb,1,'Summaries condense the main ideas.','original'),
('114.52.c.1.E',4,'After finishing research, a student can pose a new question to:','["erase the findings", "end all learning", "guide further study", "hide the sources"]'::jsonb,2,'Findings often raise new questions.','original'),
('114.52.c.1.E',3,'Which is a follow-up question drawn from a finding?','["Is it lunch yet?", "Where is my pencil?", "What is two plus two?", "What other sources might explain this difference?"]'::jsonb,3,'Follow-up questions extend inquiry.','original'),
('114.52.c.2.A',3,'Photographs of mosaics, frescoes or coins are examples of:','["visual images used as evidence", "maps of the moon", "musical scores", "verb charts"]'::jsonb,0,'Visual artifacts reveal the culture.','original'),
('114.52.c.2.A',3,'Why collect images of ancient coins and statues in a project?','["they are always fake", "they show how people lived and what they valued", "they have no meaning", "they replace all text"]'::jsonb,1,'Artifacts are primary evidence.','original'),
('114.52.c.2.B',3,'An annotated list of sources helps a researcher:','["lose track of facts", "avoid reading", "keep track of what each source offers", "add errors"]'::jsonb,2,'Annotation records each source''s value.','original'),
('114.52.c.2.C',4,'Drawing a conclusion from a range of sources requires:','["trusting the first source only", "ignoring contradictions", "skipping reading", "comparing what each source says"]'::jsonb,3,'Conclusions rest on evidence from many sources.','original'),
('114.52.c.2.C',4,'When two sources disagree, a careful researcher should:','["examine why they differ", "pick one at random", "stop researching", "delete both"]'::jsonb,0,'Disagreement is a chance to analyze evidence.','original'),
('114.52.c.2.D',4,'Bias in a source means it:','["is a poem", "leans toward one viewpoint", "has no author", "is always accurate"]'::jsonb,1,'Bias slants information.','original'),
('114.52.c.2.D',4,'A clue that a source may be biased is:','["careful citations", "named sources", "loaded, one-sided language", "balanced evidence"]'::jsonb,2,'Loaded language signals a slant.','original'),
('114.52.c.2.E',3,'Reflective writing about a project helps a student:','["copy a source", "avoid learning", "erase notes", "think about what was learned"]'::jsonb,3,'Reflection builds understanding.','original'),
('114.52.c.2.E',3,'Speaking to explore an idea aloud is useful because it:','["helps clarify thinking", "replaces research", "wastes time", "hides ideas"]'::jsonb,0,'Talking an idea through sharpens it.','original'),
('114.52.c.2.F',3,'Citing sources properly gives credit to:','["the reader only", "the original authors", "no one", "the printer"]'::jsonb,1,'Citations credit others'' work.','original'),
('114.52.c.2.F',3,'Presenting someone else''s words as your own without credit is:','["a bibliography", "paraphrasing with a citation", "plagiarism", "an index"]'::jsonb,2,'Plagiarism is using work without credit.','original'),
('114.52.c.2.G',3,'A portfolio is:','["an unrelated book", "a verb chart", "a single sentence", "a collection of a student''s work"]'::jsonb,3,'Portfolios show growth and achievement.','original'),
('114.52.c.2.G',3,'Presenting a portfolio lets a student:','["show and explain their best work", "skip the course", "avoid feedback", "hide their work"]'::jsonb,0,'A presentation shares the collection.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Languages Other Than English' and d.language = 'en'
on conflict (fingerprint) do nothing;
